"""Validate incidents.csv against schema v0.1. Usage: python validate.py [path]"""
import csv
import sys
from datetime import date

CATEGORIES = {"misuse", "loss_of_control", "security_breach",
              "dangerous_capability", "deployment_failure", "other"}
SERIOUS = {"yes", "no", "ambiguous"}
AGREEMENT = {"agree", "disagree", ""}
REQUIRED = ["id", "date_disclosed", "developer", "model", "category",
            "summary", "fmir_serious", "fmir_rationale", "sources", "coder"]


def parse_date(s):
    return date.fromisoformat(s) if s else None


def validate(path):
    errors = []
    seen = set()
    with open(path, newline="", encoding="utf-8") as f:
        for n, row in enumerate(csv.DictReader(f), start=2):
            def err(msg):
                errors.append(f"line {n} ({row.get('id', '?')}): {msg}")
            for field in REQUIRED:
                if not (row.get(field) or "").strip():
                    err(f"missing {field}")
            if row["id"] in seen:
                err("duplicate id")
            seen.add(row["id"])
            if row["category"] not in CATEGORIES:
                err(f"bad category {row['category']!r}")
            if row["fmir_serious"] not in SERIOUS:
                err(f"bad fmir_serious {row['fmir_serious']!r}")
            if row.get("agreement", "") not in AGREEMENT:
                err(f"bad agreement {row['agreement']!r}")
            if len(row["summary"].split()) > 50:
                err("summary over 50 words")
            try:
                occ = parse_date(row["date_occurred"])
                dis = parse_date(row["date_disclosed"])
                if occ and dis:
                    if dis < occ:
                        err("disclosed before occurred")
                    lag = row.get("disclosure_lag_days", "")
                    if lag and int(lag) != (dis - occ).days:
                        err("disclosure_lag_days inconsistent with dates")
            except ValueError as e:
                err(f"bad date: {e}")
            if not any(s.strip().startswith("http") for s in row["sources"].split(";")):
                err("needs at least one URL source")
    return errors


if __name__ == "__main__":
    path = sys.argv[1] if len(sys.argv) > 1 else "incidents.csv"
    problems = validate(path)
    for p in problems:
        print(p)
    print(f"{len(problems)} problem(s)")
    sys.exit(1 if problems else 0)
